'use strict';
const A=window.RETH_ATLAS,D=window.RETH_DRILL,P=window.RETH_PACK;
const $=id=>document.getElementById(id),E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
const area=A.areas.find(a=>a.id===params.get('area'))||A.areas.find(a=>a.id==='rpc');
const components=D.components[area.id];
const component=components.find(c=>c.id===params.get('c'));
const file=component&&component.files.includes(params.get('f'))?params.get('f'):null;
const directory=component&&component.files.some(p=>p.startsWith(params.get('d')||'~'))?params.get('d'):(component?.prefix||'');
const level=file?4:component?3:2;
const annotations=[...P.steps,...P.details];
let functions=[],selected=null,limit=40,filter='',text='',request;
function url(changes={}){const q=new URLSearchParams({area:area.id});if(component)q.set('c',component.id);if(directory)q.set('d',directory);if(file)q.set('f',file);if(selected)q.set('fn',selected.line);for(const [k,v]of Object.entries(changes)){if(v===null)q.delete(k);else q.set(k,v)}return 'zoom.html?'+q.toString()}
function card(href,title,desc,foot='',io='',kind=''){return `<a class="zoom-card" href="${E(href)}"><div class="card-top"><h3>${E(title)}</h3>${kind?`<span class="tag">${E(kind)}</span>`:''}</div><p>${E(desc)}</p>${io?`<div class="io-inline">${E(io)}</div>`:''}<div class="card-foot"><span>${E(foot)}</span><span>この部分を詳しく →</span></div></a>`}
function boundary(name,input,output){$('boundary').innerHTML=`<div class="boundary"><div><small>INPUT / 受け取る</small>${E(input)}</div><i>→</i><div class="unit">${E(name)}</div><i>→</i><div><small>OUTPUT / 次へ渡す</small>${E(output)}</div></div>`}
function firstDoc(path){const text=D.seed[path]??A.seed[path];if(!text)return '';return text.split('\n').filter(l=>l.startsWith('//!')).slice(0,6).map(l=>l.replace(/^\/\/!\s?/, '')).join(' ').slice(0,340)}
function parent(label,message){$('parent-context').innerHTML=`<strong>${E(label)}</strong>${E(message)}`}
function sidebar(title,body,footer=''){return `<div class="zoom-side-box"><div class="eyebrow">どこを詳しく見ている？</div><h2>${E(title)}</h2><p>${E(body)}</p>${footer}</div>`}
function shell(){const levels=['全体の責務','領域内の構成','モジュールの役割','関数と処理段階','実コード'];$('levels').innerHTML=levels.map((s,i)=>`<button class="level ${level===i+1?'active':''}" data-level="${i+1}" ${i+1>level?'disabled':''}><span>0${i+1}</span><strong>${s}</strong></button>`).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{const n=+b.dataset.level;if(n===1)location.href='explore.html';if(n===2)location.href='zoom.html?area='+area.id;if(n===3&&component)location.href=url({f:null,fn:null})});
$('zoom-crumb').innerHTML=`<a href="explore.html">Reth 全体</a> / <a href="zoom.html?area=${area.id}">${area.name}</a>${component?` / <a href="${E(url({f:null,fn:null}))}">${E(component.name)}</a>`:''}${file?` / ${E(D.roles[file]?.name||file.split('/').pop())}`:''}`;$('zoom-depth').textContent=`LEVEL 0${level} / 05 — ${levels[level-1]}`;$('zoom-up').onclick=()=>location.href=level===2?'explore.html':level===3?'zoom.html?area='+area.id:url({f:null,fn:null});}
function renderArea(){const hasRole=area.id==='rpc';$('zoom-title').textContent=area.name+'の部品は何を分担する？';$('zoom-subtitle').textContent='ここでは実装を開かず、部品ごとの責務と境界を確認します。';parent('親：RETH 全体の中の '+area.name,area.description);boundary(area.name,hasRole?'外部からの RPC 要求':'親の領域が扱う要求・データ（詳細未確認）',hasRole?'処理結果または RPC エラー':'各構成部品の結果（詳細未確認）');$('children-title').textContent='構成部品を一つ選ぶ';$('zoom-children').innerHTML=components.map(c=>card('zoom.html?area='+area.id+'&c='+c.id,c.name,c.role,c.files.length+' Rust files · '+(c.prefix||'関連ファイルを責務でまとめた範囲'),c.input+' → '+c.output,c.kind)).join('');$('zoom-side').innerHTML=sidebar(area.name+'を構成する部品','公開APIは「何を呼べるか」、共通ヘルパーは「どう処理を共通化するか」、具象実装は「どのノード部品につなぐか」を扱います。', '<div class="point"><b>まず読む場所</b>「eth_ の共通処理」→「トランザクションの送信・取得」と進むと、一段ずつ処理へ近づけます。</div>')||'';
if(!hasRole)$('zoom-side').innerHTML=sidebar('構造と意味を分けて表示', 'この領域の部品は実際の src ディレクトリから抽出しています。責務や入出力の説明が未作成の部分は、次の段階で原文のモジュールコメントを確認します。');}
function moduleName(path,isDir){if(D.roles[path])return D.roles[path].name;const name=path.replace(/\/$/,'').split('/').pop();const labels={'block.rs':'ブロックの取得・共通処理','receipt.rs':'レシートの取得・共通処理','state.rs':'状態アクセスの共通処理','call.rs':'呼び出し・実行の共通処理','mod.rs':'このモジュールの入口','lib.rs':'公開部品とモジュールの入口'};return (labels[name]||name)+(isDir?' / 内部の分担':'')}
function renderModules(){const title=component.name;$('zoom-title').textContent=title+'はどのモジュールに分かれる？';$('zoom-subtitle').textContent='役割を原文で確かめながら、担当するモジュールを選びます。';parent('親：'+area.name+' → '+title,component.role);boundary(title,component.input,component.output);$('children-title').textContent='担当する対象・モジュールを選ぶ';
const paths=component.files.filter(p=>p.startsWith(directory));const items=new Map();for(const path of paths){const rest=path.slice(directory.length);if(rest.includes('/')){const sub=directory+rest.split('/')[0]+'/';if(!items.has(sub))items.set(sub,[]);items.get(sub).push(path)}else items.set(path,[path])}
$('zoom-children').innerHTML=(area.id==='rpc'?`<details class="role-function-catalog"${directory&&directory!==component.prefix?' open':''}><summary>担当モジュールも調べる</summary>`:'')+(directory&&directory!==component.prefix?`<a class="zoom-card" href="${E(url({d:directory.replace(/[^/]+\/$/,''),f:null,fn:null}))}">↑ モジュール構成を一段戻る</a>`:'')+[...items].sort(([a],[b])=>{if(a.endsWith('transaction.rs'))return -1;if(b.endsWith('transaction.rs'))return 1;return a.localeCompare(b)}).map(([path,fs])=>{const isDir=path.endsWith('/'),role=D.roles[path];const entry=isDir?[path+'mod.rs',path+'lib.rs'].find(p=>fs.includes(p)):path;const doc=entry?firstDoc(entry):'';return card(url(isDir?{d:path,f:null,fn:null}:{f:path,fn:null}),moduleName(path,isDir),role?.role||doc||(isDir?'この範囲をさらに分け、担当するモジュールを選びます。':'責務の日本語解説は未作成です。次の段階で宣言と原文コメントを確認します。'),path+' · '+fs.length+' file'+(fs.length>1?'s':''),role?role.input+' → '+role.output:'',role?'事前作成の解説':doc?'原文コメント':'構造から抽出')}).join('')+(area.id==='rpc'?`</details><div data-component-reading="${E(component.id)}" data-component-area="rpc" data-operation-local="false"></div>`:'');window.ReadingHelp?.mount($('zoom-children'));$('zoom-side').innerHTML=sidebar('この段階で分かること', 'どのモジュールがどの対象を担当するかを確認します。ファイルの量よりも責務の違いを先に押さえます。',`<div class="point"><b>今回見ている範囲</b>${E(directory||component.name)}<br>${paths.length} Rust files</div><div class="point"><b>次の段階</b>一つのモジュールを選ぶと、関数候補・原文コメント・入出力を確認します。</div>`);}
function parseFunctions(content){const lines=content.split('\n'),result=[];let docs=[];for(let i=0;i<lines.length;i++){const line=lines[i];if(/^\s*\/\/\//.test(line)){docs.push(line.replace(/^\s*\/\/\/\s?/,''));continue}const m=line.match(/^\s*(?:pub(?:\([^)]*\))?\s+)?(?:(?:async|const|unsafe|extern\s+"[^"]+")\s+)*fn\s+(\w+)/);if(m){let signature=line.trim();for(let j=i+1;j<Math.min(lines.length,i+9)&&!/[{;]/.test(signature);j++)signature+=' '+lines[j].trim();const annotation=annotations.find(s=>s.path===file&&s.symbol.split('::').pop()===m[1]&&i+1>=s.start&&i+1<=s.end);result.push({name:m[1],line:i+1,signature:signature.replace(/\s*\{.*$/,'').slice(0,850),docs:docs.join('\n'),annotation});}if(line.trim()&&!/^\s*#\[/.test(line))docs=[];}return result;}
async function renderFunctions(){$('zoom-title').textContent=(D.roles[file]?.name||file.split('/').pop())+'の関数と役割';$('zoom-subtitle').textContent='責務と入出力を、同じページの原文と照らし合わせます。宣言候補も必要に応じて調べられます。';const role=D.roles[file];parent('親：'+component.name,role?.role||firstDoc(file)||component.role);boundary(moduleName(file,false),role?.input||'関数宣言を確認して特定する',role?.output||'関数宣言を確認して特定する');$('children-title').textContent='関数・処理単位を選ぶ';const catalog='<div id="function-catalog"><div class="zoom-empty">宣言とドキュメントコメントを取得しています…</div></div>';$('zoom-children').innerHTML=role?`<details class="role-function-catalog"><summary>別の関数・宣言候補も調べる</summary>${catalog}</details><div data-file-role-reading="${E(file)}" data-operation-local="false"></div>`:catalog;window.ReadingHelp?.mount($('zoom-children'));$('zoom-side').innerHTML=sidebar('実コードを開く前に', 'まず何のための関数か、何を受け取って何を返すかを確認します。日本語解説のない関数は、原文コメントと型を示します。');request=new AbortController();const timer=setTimeout(()=>request.abort(),20000);
try{text=D.seed[file]??A.seed[file];if(text===undefined){const r=await fetch('https://raw.githubusercontent.com/paradigmxyz/reth/'+A.commit+'/'+file.split('/').map(encodeURIComponent).join('/'),{signal:request.signal,credentials:'omit'});if(!r.ok)throw Error('HTTP '+r.status);text=await r.text();if(text.length>2000000)throw Error('ファイルが2MBを超えています')}functions=parseFunctions(text);const desired=Number(params.get('fn'));selected=functions.find(f=>f.line===desired)||functions.find(f=>f.annotation)||functions[0];renderFunctionList();renderProcess();}catch(e){$('function-catalog').innerHTML=`<div class="zoom-empty">宣言を取得できませんでした（${E(e.name==='AbortError'?'タイムアウト':e.message)}）。<br>他のモジュールを選ぶか、<button id="retry">再試行</button>してください。</div>`;$('retry').onclick=renderFunctions;}finally{clearTimeout(timer)}}
function renderFunctionList(){const list=functions;const ordered=[...list.filter(f=>f.annotation),...list.filter(f=>!f.annotation)];$('function-catalog').innerHTML='<input id="fn-filter" class="zoom-filter" aria-label="関数候補を検索" placeholder="関数名・原文コメントを検索"><div id="fn-cards"></div>';
$('fn-filter').value=filter;$('fn-filter').oninput=e=>{filter=e.target.value;limit=40;renderCards()};function renderCards(){const filtered=ordered.filter(f=>(f.name+' '+f.docs+' '+(f.annotation?.title||'')).toLowerCase().includes(filter.toLowerCase()));$('fn-cards').innerHTML=filtered.slice(0,limit).map(f=>`<button class="zoom-card ${selected?.line===f.line?'active':''}" data-fn="${f.line}"><div class="card-top"><h3>${E(f.annotation?.title||f.name)}</h3><span class="tag">${f.annotation?'事前作成の解説':'宣言候補'}</span></div><p>${E(f.annotation?.summary||f.docs.slice(0,240)||'責務は未確認です。関数名だけから挙動を推定しません。')}</p><div class="card-foot"><span>${E(f.name)} · L${f.line}</span><span>役割と処理を見る →</span></div></button>`).join('')||'<div class="zoom-empty">関数候補がありません。再エクスポートや型・定数中心のモジュール、抽出対象外の構文の可能性があります。</div>';if(filtered.length>limit)$('fn-cards').innerHTML+=`<button class="show-more" id="more-functions">次の40件（全 ${filtered.length} 候補）</button>`;document.querySelectorAll('[data-fn]').forEach(b=>b.onclick=()=>{selected=functions.find(f=>f.line===+b.dataset.fn);history.replaceState(null,'',url({fn:selected.line}));renderCards();renderProcess()});if($('more-functions'))$('more-functions').onclick=()=>{limit+=40;renderCards()};}renderCards();}
function sourceLink(){const origin=url({fn:selected.line});return selected.annotation?'reader.html?step='+selected.annotation.id+'&from='+encodeURIComponent(origin):'explore.html?file='+encodeURIComponent(file)+'&line='+selected.line+'&from='+encodeURIComponent(origin)}
function renderProcess(){$('selected-function-evidence')?.remove();if(!selected){$('zoom-side').innerHTML=sidebar('関数以外が中心のモジュール','型・定数・再エクスポートなどの責務は、この関数候補一覧では扱えません。モジュール構成へ戻って確認してください。');return}const f=selected,s=f.annotation;
const phases={rpc:["RPC の引数としてバイト列を受け取る","共通ヘルパーへ処理を渡し、結果を待つ","成功値を Ok で包んで返す。失敗は呼び出し元へ返す"],recover:["バイト列からプール用トランザクションを復元する","復元に失敗したら、この先へ進まない","Local と元のバイト列を添えて送信処理へ渡す"],submit:["元のバイト列とプール用トランザクションを分ける","設定に応じて blob sidecar を変換し、その後で外部転送の有無を判定する","転送先がなければ購読者に通知する。プール追加に成功したらハッシュを返す"],queue:["一度だけ結果を受け取る返信チャネルを作る","トランザクションと返信先を要求キューへ送る","返信を待ち、受信失敗と追加失敗を分けて伝播する"],batch:["一件の場合と、複数件の origin が同じ場合・混在する場合を分ける","件数と origin に対応するプールの追加メソッドを呼び、結果を待つ","各要求の返信チャネルへ結果を戻す"],pool:["トランザクションを検証する","検証結果を内部プールへ渡す","追加結果を取り出して返す"]};
$('zoom-side').innerHTML=`<div class="zoom-side-box"><div class="eyebrow">04 / 関数の理解</div><h2>${E(s?.title||f.name)}</h2><p>${E(s?.summary||'以下は原文の宣言・コメントです。関数の意味を自動解析した結果ではありません。')}</p>${s?`<div class="point"><b>入力</b>${E(s.input)}</div><div class="point"><b>出力・副作用</b>${E(s.output)}<br>${E(s.side)}</div><div class="point"><b>失敗・分岐</b>${E(s.branch)}</div>`:`<div class="point"><b>原文のドキュメントコメント</b><div class="doc-original">${E(f.docs||'コメントなし。責務と入出力の意味は未確認です。')}</div></div><div class="fn-signature">${E(f.signature)}</div>`}${s?`<button type="button" class="next-code" data-reading-ref="tx:${E(s.id)}" data-reading-target-line="${f.line}">このページの該当コードを選ぶ →</button>`:''}<a class="next-code" href="${E(sourceLink())}">原文の行範囲・メモを開く →</a><p class="zoom-note">この関数の位置に移動します。戻ると、親の構成と選択した関数を復元します。</p></div>${s?`<div class="process-box"><div class="eyebrow">処理の詳細化</div><h3>${E(s.question)}</h3>${(phases[s.id]||[s.detail,s.branch]).map((p,i)=>`<div class="process-row"><span>${i+1}</span><p>${E(p)}</p></div>`).join('')}<p class="zoom-note">説明用の段階分け。対応する原文を、このページの補助コメントと照らし合わせます。</p></div>`:''}<p class="zoom-note">一覧はテキスト上の fn 宣言から抽出した候補です。trait 宣言・実装・テストを含み、同名関数やマクロを完全には解決しません。</p>`;if(s){const evidence=document.createElement('div');evidence.id='selected-function-evidence';evidence.dataset.readingReference='tx:'+s.id;evidence.dataset.helpCommit=P.commit;if(P.steps.some(step=>step.id===s.id))evidence.dataset.referenceOperation=s.id;$('zoom-children').append(evidence);window.ReadingHelp?.mount(evidence);}}
shell();if(level===2)renderArea();else if(level===3)renderModules();else renderFunctions();
